CREATE TABLE analyses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), filename text NOT NULL, quality_score integer NOT NULL, quality_label text NOT NULL, blur_score double precision, underexposure_score double precision, overexposure_score double precision, noise_score double precision, corruption_score double precision, defect_score double precision, confidence double precision, uncertainty double precision, uncertainty_label text, image_statistics jsonb, feature_vector jsonb, explanation jsonb, model_version text NOT NULL, processing_time_ms integer, storage_key text, heatmap_storage_key text);